import { cn } from "@/lib/utils"

/**
 * Twenty square segments and a number. The band decides what the AI may do:
 * 80+ plan · 50–79 draft · below 50 check only (segments turn to the signal colour).
 */
export const CONFIDENCE_ACT = 80
export const CONFIDENCE_REVIEW = 50

export function confidenceBand(value: number) {
  return value >= CONFIDENCE_ACT ? "plan" : value >= CONFIDENCE_REVIEW ? "draft" : "check"
}

export interface ConfidenceMeterProps {
  value: number
  /** A new reading is coming in. */
  updating?: boolean
  className?: string
}

export function ConfidenceMeter({ value, updating = false, className }: ConfidenceMeterProps) {
  const on = Math.round((value / 100) * 20)
  const low = value < CONFIDENCE_REVIEW
  return (
    <div data-slot="confidence-meter" data-band={confidenceBand(value)} className={cn("grid w-full min-w-[220px] gap-1.5", className)}>
      <div className="flex items-baseline justify-between">
        <span className="font-mono text-[11px] uppercase tracking-[0.05em] text-muted-foreground">Confidence</span>
        <span className="font-mono text-xs">{value}%</span>
      </div>
      <div className="flex h-2 gap-0.5" role="meter" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100} aria-label="AI confidence">
        {Array.from({ length: 20 }, (_, i) => (
          <i
            key={i}
            className={cn("flex-1", i < on ? (low ? "bg-signal" : "bg-foreground") : "bg-border", updating && "animate-pulse motion-reduce:animate-none")}
            style={updating ? { animationDelay: `${(i % 4) * 120}ms` } : undefined}
          />
        ))}
      </div>
    </div>
  )
}
